package com.example.gameworkbench.service; import static org.assertj.core.api.Assertions.*; import java.util.*; import org.junit.jupiter.api.Test;
class RetrievalServiceTest { @Test void enforcesProjectAndStatus(){var store=new InMemoryVectorStore(); var p=new FakeEmbeddingProvider();store.upsert("a",p.embed(List.of("q")).get(0),Map.of("projectId","1","status","ACTIVE","chunkUuid","c","documentUuid","d","documentVersion","1","embeddingModel",p.model()));store.upsert("b",p.embed(List.of("q")).get(0),Map.of("projectId","2","status","ACTIVE","chunkUuid","x","documentUuid","z","documentVersion","1","embeddingModel",p.model()));var out=new ProjectRetrievalService(p,store).retrieve(new RetrievalRequest(1L,"q",5,0,100));assertThat(out).hasSize(1);assertThat(out.getFirst().chunkUuid()).isEqualTo("c");} }
